// NBIRTH: the edge node's own birth certificate, published once before any DBIRTH.
// Real Sparkplug B NBIRTH also carries a bdSeq (birth/death sequence) metric, omitted
// here because the ingestion engine's JSON-fallback parser (used by this simulator)
// only understands string_value/double_value/boolean_value metrics, not long_value.
//
// AN NBIRTH RESETS EVERYTHING FOR THIS EDGE NODE. The sequence counter goes to 0 because the
// specification says so, and the report-by-exception cache is cleared because a consumer that
// has just been handed a fresh baseline must be told the current value of every metric again
// rather than have it suppressed as "unchanged since before the birth".
global.set('sp_seq', 0);
global.set('rbe_cache', {});

const topic = 'spBv1.0/ACS-Cymru/NBIRTH/gwy100000000000400080000';
const spbNBirthPayload = {
    timestamp: Date.now(),
    // Factory+ birth profile. The payload `uuid` identifies this as a Factory+ Sparkplug
    // packet; Instance_UUID and Schema_UUID are the asset's RFC4122 identity and the model
    // it conforms to. Additive -- the topic's sparkplug_id remains this platform's identity.
    //
    // NO Schema_UUID HERE, deliberately. Factory+'s component schema
    // (05688a03-730e-4cda-9932-172e2c62e45c) asserts that the publisher is a Factory+
    // COMPONENT serving a Service_UUID at a Service_URL. This edge node is not one, so
    // claiming it would assert an interoperability that does not exist. Instance_UUID is
    // a fact about the gateway; a schema id it does not implement would be a fiction.
    uuid: '11ad7b32-1d32-4c4a-b0c9-fa049208939a',
    metrics: [
        { name: 'Instance_UUID', string_value: '10000000-0000-4000-8000-000000000001', datatype: 12 },
        { name: 'Gateway_Status', string_value: 'ONLINE', datatype: 12 }
    ],
    seq: 0
};
return { topic: topic, payload: JSON.stringify(spbNBirthPayload), qos: 0, retain: false };

// Periodic rebirth so a consumer that starts after Node-RED still receives the
// birth certificate. Stays silent while the device is in its DDEATH state, so the
// DDEATH demo is not undone by the next rebirth tick.
if (global.get('device_alive') === false) {
    return null;
}
global.set('device_alive', true);

// Sparkplug B SEQUENCE NUMBER. NBIRTH is seq 0 and every subsequent message this edge node
// sends increments by one, wrapping 255 -> 0. It was previously Math.random(), which is not a
// sequence at all: it is what lets a consumer detect that it MISSED a message, and under
// report-by-exception that is the ONLY way it can find out -- a metric that stopped arriving
// looks exactly like a metric that stopped changing.
function nextSeq() {
    const n = ((global.get('sp_seq') || 0) + 1) % 256;
    global.set('sp_seq', n);
    return n;
}

// The device's LIVE readings and their Sparkplug datatypes, in one place so a birth
// certificate and the DDATA that follows it cannot disagree about either.
const TELEMETRY_DATATYPE = {
    'Systems/TEMPERATURE': 10,
    'Axes/DISPLACEMENT': 10,
    'Controller/EXECUTION': 12,
    'Controller/EMERGENCY_STOP': 12
};

// THE SIMULATED SIGNAL HAD TO BECOME PHYSICALLY PLAUSIBLE FOR A DEADBAND TO MEAN ANYTHING.
// Two things were wrong with it for RBE purposes, and both made the deadband decorative:
//
//   NOISE ABOVE THE DEADBAND. The jitter was `Math.random() * 1.5` -- 1.5 degC, three times
//   the 0.5 degC deadband below -- so it tripped the change test on its own and RBE would
//   have suppressed almost nothing. A deadband is only meaningful above an instrument's
//   noise floor. It is now +/-0.15 degC, and symmetric: the old term only ever added heat,
//   biasing the mean 0.75 degC above the 42 degC this flow claims to simulate.
//
//   A 38-SECOND THERMAL CYCLE. The sine ran at `Date.now() / 6000` -- a 10 degC peak-to-peak
//   swing every 38 seconds, or up to 4 degC between two 5-second scans. No machine's
//   temperature moves like that, and against a real signal every scan is a genuine exception,
//   so RBE correctly reports nearly all of them and appears to achieve nothing. At /25000 the
//   cycle is ~2.6 minutes, which is a plausible thermal response to varying load and moves
//   ~1 degC per scan at its steepest -- so the flanks report and the turning points fall
//   quiet, which is what report-by-exception is supposed to look like.
function currentReadings() {
    const temp = global.get('temp_override');
    const disp = global.get('displacement_override');
    return {
        'Systems/TEMPERATURE': temp !== undefined ? temp
            : +(42.0 + Math.sin(Date.now() / 25000) * 5.0 + ((Math.random() - 0.5) * 0.3)).toFixed(2),
        'Axes/DISPLACEMENT': disp !== undefined ? disp : 1.45,
        'Controller/EXECUTION': global.get('status_override') || 'ACTIVE',
        'Controller/EMERGENCY_STOP':
            (global.get('safety_override') !== undefined ? global.get('safety_override') : true)
                ? 'ARMED' : 'TRIGGERED'
    };
}

function metricFor(name, value) {
    const datatype = TELEMETRY_DATATYPE[name];
    const metric = { name: name, datatype: datatype };
    if (datatype === 12) { metric.string_value = String(value); }
    else if (datatype === 11) { metric.boolean_value = !!value; }
    else { metric.double_value = Number(value); }
    return metric;
}

// THE BIRTH CERTIFICATE IS THE RBE BASELINE, so it declares the values the device ACTUALLY
// holds right now rather than nominal placeholders, and seeds the cache with exactly what it
// published. Declaring 42.0 while the sensor reads 44.3 would make the first DDATA after every
// rebirth a correction of a number no instrument ever produced.
const now = Date.now();
const readings = currentReadings();
const cache = {};
const telemetryMetrics = Object.keys(TELEMETRY_DATATYPE).map(function (name) {
    cache[name] = { v: readings[name], t: now };
    return metricFor(name, readings[name]);
});
global.set('rbe_cache', cache);

const topic = 'spBv1.0/ACS-Cymru/DBIRTH/gwy100000000000400080000/dev200000000000400080000';
const spbBirthPayload = {
    timestamp: now,
    // Factory+ birth profile. The payload `uuid` identifies this as a Factory+ Sparkplug
    // packet; Instance_UUID and Schema_UUID are the asset's RFC4122 identity and the model
    // it conforms to. Additive -- the topic's sparkplug_id remains this platform's identity.
    uuid: '11ad7b32-1d32-4c4a-b0c9-fa049208939a',
    metrics: [
        { name: 'Instance_UUID', string_value: '20000000-0000-4000-8000-000000000002', datatype: 12 },
        { name: 'Schema_UUID',   string_value: 'e3333333-4444-5555-6666-777777777777', datatype: 12 },
        { name: 'Asset_ID',          string_value: 'dev200000000000400080000',  datatype: 12 },
        { name: 'Asset_Name', string_value: 'Simulated_CNC_01', datatype: 12 },
        { name: 'Controller/FIRMWARE',  string_value: 'v3.2.0-industrial', datatype: 12 },
        { name: 'SERIAL_NUMBER',     string_value: 'SN-CNC-8832',       datatype: 12 },
        { name: 'max_temp_threshold',double_value: 85.0,                datatype: 10 },
        { name: 'safety_interlock',  boolean_value: true,               datatype: 11 }
    ].concat(
        // Sparkplug B requires DBIRTH to declare every metric the device will report in DDATA.
        // These are the same four the RBE cache above was just seeded with.
        telemetryMetrics
    ),
    seq: nextSeq()
};
return { topic: topic, payload: JSON.stringify(spbBirthPayload), qos: 0, retain: false };

// REPORT BY EXCEPTION. This node is SCANNED on a timer; it PUBLISHES only when a metric has
// actually moved. Sparkplug B DDATA means "these metrics changed" -- a fixed-interval payload
// carrying every metric whether it moved or not is not DDATA, it is polling with extra steps,
// and downstream it writes a row per metric per scan into the historian for readings nobody
// took. This node used to emit six metrics every five seconds forever.
//
// THREE WAYS A METRIC QUALIFIES AS AN EXCEPTION:
//   1. It has no cached value yet -- the first scan after a birth.
//   2. It is analogue and has moved by at least its DEADBAND. Without a deadband the last
//      digit of a real sensor dithers continuously and RBE suppresses nothing at all.
//   3. It is discrete (string/bool) and changed at all. No deadband applies to a state.
//
// MAX_SILENCE_MS IS THE KEEPALIVE, AND IT IS NOT A BETRAYAL OF RBE -- it is what makes RBE
// safe to consume. A value that is genuinely constant is indistinguishable, from the
// consumer's side, from a device that died silently, and every staleness check downstream
// reads absence as failure: the dashboard's latest-value query filters on a time window, and
// Grafana's alerting treats no-data as a condition. Republishing an unchanged metric every
// five minutes bounds that ambiguity while still cutting wire and historian volume ~60x
// against the 5s full payload this replaces.
//
// IDENTITY METRICS ARE GONE FROM DDATA. Asset_ID and Asset_Name are immutable, declared in
// DBIRTH, and discarded by ingestion.py's IDENTITY_METRICS filter before they ever reach the
// historian -- so publishing them on every scan was pure wire overhead. The TOPIC is what
// identifies the asset (see resolve_wire_identity), and an alias-encoded DDATA from a real
// gateway carries no Asset_ID either.
if (global.get('device_alive') === false) {
    return null;
}

// Tuned to the instruments: 0.5 degC on a thermocouple and 0.05 mm on a linear axis are both
// comfortably above their noise floor and below any movement an operator would care about.
const DEADBAND = {
    'Systems/TEMPERATURE': 0.5,
    'Axes/DISPLACEMENT': 0.05
};
const MAX_SILENCE_MS = 300000;

// Sparkplug B SEQUENCE NUMBER. NBIRTH is seq 0 and every subsequent message this edge node
// sends increments by one, wrapping 255 -> 0. It was previously Math.random(), which is not a
// sequence at all: it is what lets a consumer detect that it MISSED a message, and under
// report-by-exception that is the ONLY way it can find out -- a metric that stopped arriving
// looks exactly like a metric that stopped changing.
function nextSeq() {
    const n = ((global.get('sp_seq') || 0) + 1) % 256;
    global.set('sp_seq', n);
    return n;
}

// The device's LIVE readings and their Sparkplug datatypes, in one place so a birth
// certificate and the DDATA that follows it cannot disagree about either.
const TELEMETRY_DATATYPE = {
    'Systems/TEMPERATURE': 10,
    'Axes/DISPLACEMENT': 10,
    'Controller/EXECUTION': 12,
    'Controller/EMERGENCY_STOP': 12
};

// THE SIMULATED SIGNAL HAD TO BECOME PHYSICALLY PLAUSIBLE FOR A DEADBAND TO MEAN ANYTHING.
// Two things were wrong with it for RBE purposes, and both made the deadband decorative:
//
//   NOISE ABOVE THE DEADBAND. The jitter was `Math.random() * 1.5` -- 1.5 degC, three times
//   the 0.5 degC deadband below -- so it tripped the change test on its own and RBE would
//   have suppressed almost nothing. A deadband is only meaningful above an instrument's
//   noise floor. It is now +/-0.15 degC, and symmetric: the old term only ever added heat,
//   biasing the mean 0.75 degC above the 42 degC this flow claims to simulate.
//
//   A 38-SECOND THERMAL CYCLE. The sine ran at `Date.now() / 6000` -- a 10 degC peak-to-peak
//   swing every 38 seconds, or up to 4 degC between two 5-second scans. No machine's
//   temperature moves like that, and against a real signal every scan is a genuine exception,
//   so RBE correctly reports nearly all of them and appears to achieve nothing. At /25000 the
//   cycle is ~2.6 minutes, which is a plausible thermal response to varying load and moves
//   ~1 degC per scan at its steepest -- so the flanks report and the turning points fall
//   quiet, which is what report-by-exception is supposed to look like.
function currentReadings() {
    const temp = global.get('temp_override');
    const disp = global.get('displacement_override');
    return {
        'Systems/TEMPERATURE': temp !== undefined ? temp
            : +(42.0 + Math.sin(Date.now() / 25000) * 5.0 + ((Math.random() - 0.5) * 0.3)).toFixed(2),
        'Axes/DISPLACEMENT': disp !== undefined ? disp : 1.45,
        'Controller/EXECUTION': global.get('status_override') || 'ACTIVE',
        'Controller/EMERGENCY_STOP':
            (global.get('safety_override') !== undefined ? global.get('safety_override') : true)
                ? 'ARMED' : 'TRIGGERED'
    };
}

function metricFor(name, value) {
    const datatype = TELEMETRY_DATATYPE[name];
    const metric = { name: name, datatype: datatype };
    if (datatype === 12) { metric.string_value = String(value); }
    else if (datatype === 11) { metric.boolean_value = !!value; }
    else { metric.double_value = Number(value); }
    return metric;
}

const now = Date.now();
const cache = global.get('rbe_cache') || {};
const readings = currentReadings();
const changed = [];

Object.keys(readings).forEach(function (name) {
    const value = readings[name];
    const previous = cache[name];
    let publish;

    if (!previous) {
        publish = true;
    } else if (typeof value === 'number' && typeof previous.v === 'number') {
        publish = Math.abs(value - previous.v) >= (DEADBAND[name] || 0);
    } else {
        publish = value !== previous.v;
    }

    // Measured from the last PUBLISH, not the last scan, so a metric sitting inside its
    // deadband is still refreshed on a bounded schedule.
    if (!publish && (now - previous.t) >= MAX_SILENCE_MS) {
        publish = true;
    }

    if (publish) {
        cache[name] = { v: value, t: now };
        changed.push(metricFor(name, value));
    }
});

// NOTHING MOVED, SO NOTHING IS PUBLISHED. This return is the entire point of the node: no
// message on the wire, no row in the hypertable, and the last known value stays exactly where
// a consumer already has it. The sequence number is deliberately NOT consumed here -- a
// suppressed sample is not a message, and burning a seq for it would look to the ingestion
// daemon like the message it never sent had been lost.
if (changed.length === 0) {
    return null;
}

global.set('rbe_cache', cache);

const topic = 'spBv1.0/ACS-Cymru/DDATA/gwy100000000000400080000/dev200000000000400080000';
const spbDataPayload = {
    timestamp: now,
    metrics: changed,
    seq: nextSeq()
};
return { topic: topic, payload: JSON.stringify(spbDataPayload), qos: 0, retain: false };

global.set('device_alive', false);
// The death certificate invalidates the baseline: whatever the RBE cache holds describes a
// device that is no longer publishing, and the DBIRTH that eventually follows must re-declare
// every metric rather than have them suppressed as unchanged.
global.set('rbe_cache', {});

// Sparkplug B SEQUENCE NUMBER. NBIRTH is seq 0 and every subsequent message this edge node
// sends increments by one, wrapping 255 -> 0. It was previously Math.random(), which is not a
// sequence at all: it is what lets a consumer detect that it MISSED a message, and under
// report-by-exception that is the ONLY way it can find out -- a metric that stopped arriving
// looks exactly like a metric that stopped changing.
function nextSeq() {
    const n = ((global.get('sp_seq') || 0) + 1) % 256;
    global.set('sp_seq', n);
    return n;
}

const topic = 'spBv1.0/ACS-Cymru/DDEATH/gwy100000000000400080000/dev200000000000400080000';
const spbDeathPayload = {
    timestamp: Date.now(),
    metrics: [
        { name: 'Asset_ID', string_value: 'dev200000000000400080000', datatype: 12 },
        { name: 'Asset_Name', string_value: 'Simulated_CNC_01', datatype: 12 }
    ],
    seq: nextSeq()
};
return { topic: topic, payload: JSON.stringify(spbDeathPayload), qos: 0, retain: false };

// BONUS TEST -- overheat. This node now only sets the CONDITION; the DDATA builder downstream
// is what publishes it. That is what report-by-exception means: an alarm is an exception like
// any other, and routing it through the same change detector keeps the RBE cache in step. When
// this node published its own payload the cache went stale behind it, and the next scan
// re-sent all four metrics as though they had just moved.
global.set('device_alive', true);
global.set('temp_override', 95.0);
global.set('displacement_override', 8.92);
global.set('status_override', 'INTERRUPTED');
global.set('safety_override', false);
return msg;

// BONUS TEST -- restore normal operation. Sets the condition and lets the DDATA builder
// publish the change, exactly as the overheat node does.
//
// 'ACTIVE', NOT 'RUNNING'. This node used to set status_override to 'RUNNING' while the
// payload it published alongside said 'ACTIVE' -- so after one press the device reported a
// value that is not in the MTConnect EXECUTION vocabulary at all (0002_seed_data.sql), and
// every EXECUTION reading from then on was Unmodelled.
//
// The overrides are CLEARED rather than pinned, so temperature returns to its live sine and
// displacement to its nominal 1.45 instead of freezing at whatever this node last stated.
global.set('device_alive', true);
global.set('temp_override', undefined);
global.set('displacement_override', undefined);
global.set('status_override', 'ACTIVE');
global.set('safety_override', true);
return msg;

// Sparkplug B SEQUENCE NUMBER. NBIRTH is seq 0 and every subsequent message this edge node
// sends increments by one, wrapping 255 -> 0. It was previously Math.random(), which is not a
// sequence at all: it is what lets a consumer detect that it MISSED a message, and under
// report-by-exception that is the ONLY way it can find out -- a metric that stopped arriving
// looks exactly like a metric that stopped changing.
function nextSeq() {
    const n = ((global.get('sp_seq') || 0) + 1) % 256;
    global.set('sp_seq', n);
    return n;
}

const topic = 'spBv1.0/ACS-Cymru/NDATA/gwy100000000000400080000';
const spbHeartbeatPayload = {
    timestamp: Date.now(),
    metrics: [
        { name: 'Gateway_Status', string_value: 'ONLINE', datatype: 12 }
    ],
    seq: nextSeq()
};
return { topic: topic, payload: JSON.stringify(spbHeartbeatPayload), qos: 0, retain: false };

// Supabase posts the payload built by dispatch_device_quarantine_webhook().
const e = msg.payload || {};
node.warn(
    `QUARANTINE: ${e.sparkplug_id || e.device_id} (${e.name || "unnamed"}) ` +
    `reason=${e.quarantine_reason || "unspecified"} ` +
    `identity_source=${e.identity_source || "unknown"}`
);

// Replace this node to act on the event -- raise a ticket, page an operator, light an
// andon. The 200 below is returned regardless: pg_net does not retry, so failing the
// response would lose the event rather than redeliver it.
msg.statusCode = 200;
msg.payload = { received: true, sparkplug_id: e.sparkplug_id || null };
return msg;

// Answer a Sparkplug NCMD carrying `Node Control/Rebirth` by re-publishing this node's
// NBIRTH and then its DBIRTH -- which is what the specification requires of an Edge Node,
// and what lets the ingestion daemon recover its metric ALIAS TABLE after a restart.
//
// WHY A SUBSTRING PROBE AND NOT A PROTOBUF PARSE. The daemon publishes a real Sparkplug
// protobuf payload, and this image ships no protobuf library. A length-delimited protobuf
// string field carries its bytes verbatim, so the metric name appears literally in the
// buffer -- searching for it is reliable here even though it would not be a general decoder.
// A JSON payload is handled too, because the daemon's own fallback parser accepts one.
const REBIRTH = 'Node Control/Rebirth';
const MY_NODE = 'gwy100000000000400080000';

// Only answer a command addressed to THIS edge node. spBv1.0/<group>/NCMD/<edge_node>
const parts = (msg.topic || '').split('/');
if (parts[3] !== MY_NODE) { return null; }

const raw = msg.payload;
let wantsRebirth = false;

if (raw && typeof raw === 'object' && !Buffer.isBuffer(raw)) {
    // Already-parsed JSON.
    wantsRebirth = (raw.metrics || []).some(m => m.name === REBIRTH) || raw.Rebirth === true;
} else {
    const text = Buffer.isBuffer(raw) ? raw.toString('binary') : String(raw || '');
    try {
        const parsed = JSON.parse(text);
        wantsRebirth = (parsed.metrics || []).some(m => m.name === REBIRTH) || parsed.Rebirth === true;
    } catch (e) {
        wantsRebirth = text.indexOf(REBIRTH) !== -1;
    }
}

if (!wantsRebirth) { return null; }

node.warn('NCMD Node Control/Rebirth received -- re-publishing NBIRTH and DBIRTH');
// Both outputs carry an empty message: the birth builders construct their payloads from
// scratch and read nothing from the input. NBIRTH is wired first because it RESETS the
// node's alias table, and the DBIRTH that follows must merge into a fresh one.
return [{}, {}];

// ---------------------------------------------------------------------------------------------
// Sparkplug B device simulation with report-by-exception.
//
// THE RBE CACHE LIVES IN NODE CONTEXT, WHICH IS PER SUBFLOW INSTANCE. flow.* and global.* are
// shared across every instance on the tab, so a cache kept there would have all five devices
// reading and writing one another's last-published values: four of them would publish nothing and
// the fifth would publish nonsense. It would look like a broker fault.
//
// The sandbox name is `context`, NOT `node.context()` -- the latter is the runtime API and is
// not exposed to a function node, where it throws "node.context is not a function".
// ---------------------------------------------------------------------------------------------
const DEVICE_ID   = env.get('DEVICE_ID');
const DEVICE_NAME = env.get('DEVICE_NAME');
const GATEWAY_ID  = env.get('GATEWAY_ID');
const KIND        = env.get('KIND');
const GROUP       = env.get('SPARKPLUG_GROUP') || 'ACS-Cymru';

const BIRTH_EVERY_SCANS = Number(env.get('BIRTH_EVERY_SCANS') || 180);   // 15 min at a 5s scan
const MAX_SILENCE_MS    = 5 * 60 * 1000;

const cache   = context.get('rbe')   || {};
const lastPub = context.get('lastAt') || {};
let   scan    = Number(context.get('scan') || 0);
let   seq     = Number(context.get('seq')  || 0);

scan += 1;

// Fault flags are GLOBAL on purpose -- they are set by inject nodes outside the subflow and are a
// property of the scenario, not of one device. Only the targeted device reads its own.
const thermalFault = global.get('fault_thermal') === true;
const estopFault   = global.get('fault_estop') === true;

const t = Date.now();
const wave = (periodMs, phase) => Math.sin((t / periodMs) * 2 * Math.PI + (phase || 0));
const noise = (amp) => (Math.random() - 0.5) * 2 * amp;

// ---------------------------------------------------------------------------------------------
// Per-class metric sets. Deadbands sit ABOVE the simulated noise floor -- a deadband smaller than
// the noise is tripped by the noise alone and suppresses nothing, which is report-by-exception in
// name only.
// ---------------------------------------------------------------------------------------------
let metrics = [];

if (KIND === 'cnc') {
  const running = !estopFault && wave(90000) > -0.6;
  const temp = thermalFault && DEVICE_NAME === 'CNC_Mill_01'
    ? 95 + noise(0.4)
    : 42 + wave(120000) * 3 + noise(0.15);

  metrics = [
    { name: 'Axes/X/POSITION',        type: 'double', value: 150 + wave(30000) * 120 + noise(0.02), band: 0.5 },
    { name: 'Axes/Y/POSITION',        type: 'double', value: 100 + wave(41000, 1.1) * 80 + noise(0.02), band: 0.5 },
    { name: 'Systems/TEMPERATURE',    type: 'double', value: temp, band: 0.5 },
    { name: 'Controller/EXECUTION',   type: 'string', value: estopFault ? 'INTERRUPTED' : (running ? 'ACTIVE' : 'READY') },
    { name: 'Controller/EMERGENCY_STOP', type: 'string', value: estopFault ? 'TRIGGERED' : 'ARMED' },
  ];

  // Published for the OEE aggregator, which is a different device and cannot read this instance's
  // context. A global keyed by device id is the narrowest thing that crosses that boundary.
  global.set('state_' + DEVICE_ID, metrics.find(m => m.name === 'Controller/EXECUTION').value);
}

if (KIND === 'robot') {
  const stopped = estopFault;
  metrics = [
    { name: 'MotionDevice/ActualPosition', type: 'double', value: 400 + wave(25000) * 350 + noise(0.02), band: 1.0 },
    { name: 'MotionDevice/ActualSpeed',    type: 'double', value: stopped ? 0 : 180 + wave(25000, 1.6) * 150, band: 5.0 },
    { name: 'MotionDevice/EmergencyStop',  type: 'boolean', value: stopped },
    { name: 'Machine/OperationalMode',     type: 'string', value: stopped ? 'STOPPED' : 'AUTOMATIC' },
    // Compressed air, not electricity. OPC 40001-4 as seeded models energy MEDIA -- pressure,
    // volume, flow -- and carries no active-power concept, so this is the energy metric that has
    // a published semantic id behind it. See the note in scripts/generate-simulator-flow.mjs.
    { name: 'Energy/VolumeFlowRate',       type: 'double', value: stopped ? 0.4 : 12 + wave(60000) * 3 + noise(0.05), band: 0.25 },
  ];
}

if (KIND === 'agv') {
  // Flattened state fields only. VDA 5050 is a complete bidirectional protocol with its own
  // identity scheme keyed on manufacturer + serialNumber; adopting it would introduce a second
  // identity path competing with sparkplug_id. docs/vocabularies.md settles this: take the scalar
  // state fields as a vocabulary and leave the protocol in an edge adapter.
  const moving = wave(45000) > -0.3;
  metrics = [
    { name: 'MotionDevice/ActualSpeed',  type: 'double', value: moving ? 900 + wave(45000) * 300 : 0, band: 10 },
    { name: 'MotionDevice/OnPath',       type: 'boolean', value: moving },
    { name: 'Machine/OperationalMode',   type: 'string', value: moving ? 'AUTOMATIC' : 'MANUAL' },
  ];
}

if (KIND === 'bms') {
  metrics = [
    { name: 'BMS/ZONE_TEMPERATURE',   type: 'double', value: 21.5 + wave(600000) * 1.5 + noise(0.1), band: 0.3 },
    { name: 'BMS/ZONE_HUMIDITY',      type: 'double', value: 45 + wave(900000, 0.8) * 6 + noise(0.2), band: 1.0 },
    { name: 'BMS/SUPPLY_AIR_FLOW',    type: 'double', value: 320 + wave(300000) * 40 + noise(0.5), band: 5.0 },
