const valueField = (m) => {
  if (m.type === 'double') return { datatype: 10, double_value: Number(m.value.toFixed(3)) };
  if (m.type === 'boolean') return { datatype: 11, boolean_value: Boolean(m.value) };
  return { datatype: 12, string_value: String(m.value) };
};

